import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import {resolve} from 'node:path';
import {ConnectionManager} from '../../packages/core/src/connections.js';
import {DatabaseDefinitions} from '../../packages/core/src/database-definitions.js';
import {StructureComparisons} from '../../packages/core/src/structure-comparisons.js';
import {ProfileSchema,type ConnectionProfile} from '../../packages/protocol/src/index.js';
import {ddlQuote} from '../../packages/core/src/ddl-syntax.js';
export async function structureComparisonContract(profile:ConnectionProfile,password:string){
 const prefix='struct_'+randomUUID().replaceAll('-','').slice(0,9),source={...profile,id:prefix+'_source'},target={...profile,id:prefix+'_target'},local=ProfileSchema.parse({id:prefix+'_local',name:'Structure SQLite',driver:'sqlite',storage:'memory'}),profiles=[source,target,local],manager=new ConnectionManager({list:()=>profiles,save:async()=>{},remove:async()=>{}},{runnerPath:resolve('dist/sqlite-runner.cjs')}),definitions=new DatabaseDefinitions(manager),comparisons=new StructureComparisons(manager,definitions),d=profile.driver,mysql=d!=='postgresql',q=(n:string)=>ddlQuote(n,d),schema=mysql?profile.database!:'public',name=(n:string)=>q(schema)+'.'+q(prefix+n),from=name('_a'),to=name('_b'),audit=name('_audit');
 try{
  for(const p of [source,target])await manager.setPassword(p.id,password,'session');const a=await manager.connect(source.id),b=await manager.connect(target.id),sqlite=await manager.connect(local.id);
  if(mysql)await a.query("SET SESSION sql_mode=CONCAT(@@SESSION.sql_mode,',NO_BACKSLASH_ESCAPES,ANSI_QUOTES')");
  await a.query(`CREATE TABLE ${from}(id INT PRIMARY KEY${mysql?' AUTO_INCREMENT':''},v VARCHAR(80) NOT NULL DEFAULT 'ready',n BIGINT,payload ${mysql?'BLOB':'BYTEA'},parent INT,added VARCHAR(80) DEFAULT 'C:\\new\\中文''quote',CONSTRAINT ${q(prefix+'_self_a')} FOREIGN KEY(parent) REFERENCES ${from}(id),CONSTRAINT ${q(prefix+'_ck')} CHECK(length(v)>0))${mysql?" COMMENT='AUTO_INCREMENT=88 kept C:\\path'":''}`);
  await b.query(`CREATE TABLE ${to}(id INT PRIMARY KEY${mysql?' AUTO_INCREMENT':''},v VARCHAR(40),n BIGINT,payload ${mysql?'BLOB':'BYTEA'},parent INT,extra TEXT,CONSTRAINT ${q(prefix+'_self_b')} FOREIGN KEY(parent) REFERENCES ${to}(id))`);await a.query(`CREATE INDEX ${q(prefix+'_idx')} ON ${from}(v)`);await b.query(`CREATE TABLE ${audit}(id INT)`);
  if(mysql)await b.query(`CREATE TRIGGER ${name('_tr')} AFTER UPDATE ON ${to} FOR EACH ROW INSERT INTO ${audit} VALUES(NEW.id)`);
  else{await b.query(`CREATE FUNCTION ${name('_fn')}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO ${audit} VALUES(NEW.id);RETURN NEW;END $$`);await b.query(`CREATE TRIGGER ${q(prefix+'_tr')} AFTER UPDATE ON ${to} FOR EACH ROW EXECUTE FUNCTION ${name('_fn')}()`);}
  await a.query(`INSERT INTO ${from}(id,v,n) VALUES(2,'source',3)`);await b.query(`INSERT INTO ${to}(id,v,n,payload) VALUES(77,'target',9223372036854775807,${mysql?"x'00ff'":"decode('00ff','hex')"})`);if(mysql){await b.query(`INSERT INTO ${to}(id,v) VALUES(500,'deleted')`);await b.query(`DELETE FROM ${to} WHERE id=500`);}
  // Different lexical modes on actual server sessions, not fabricated SHOW CREATE output.
  const lease=manager.lease.bind(manager);if(mysql)manager.lease=async(id,owner)=>{const s=await lease(id,owner);if(id===source.id)await s.query("SET SESSION sql_mode=CONCAT(@@SESSION.sql_mode,',NO_BACKSLASH_ESCAPES,ANSI_QUOTES')");return s;};
  const endpoints=[{profileId:source.id,table:from},{profileId:target.id,table:to}] as const,c=await comparisons.compare(...endpoints);assert(c.canPrepare,JSON.stringify(c.notes));if(mysql)assert.match(c.source.tableStructure!.indexes.find(i=>i.name===prefix+'_self_a')!.definition,/^(KEY|INDEX) /);const oldOid=mysql?undefined:JSON.parse(c.target.tableStructure!.identity).oid,draft=await comparisons.prepare(c.token,c.differences.filter(v=>v.change!=='equal'&&v.selectable).map(v=>v.id));assert(!draft.sql.includes('REFERENCES '+from));if(mysql)assert(draft.sql.includes('AUTO_INCREMENT=88 kept'));assert.equal((await b.query(`SELECT v FROM ${to}`)).rows[0]?.c0,'target');
  const preview=await definitions.preview(draft.baseline,draft.sql);assert.equal(preview.kind,'preview');if(preview.kind!=='preview')throw Error('Expected migration');const report=await definitions.apply(target.id,preview.preview.token);assert.equal(report.status,'succeeded',report.error);assert(report.snapshot);if(!mysql)assert.equal(JSON.parse(report.snapshot.tableStructure!.identity).oid,oldOid);
  const row=(await b.query(`SELECT id,v,n,payload,added FROM ${to} WHERE id=77`)).rows[0]!;assert.equal(row.c0,77);assert.equal(row.c1,'target');assert.deepEqual(row.c2,{type:'integer',value:'9223372036854775807'});assert.deepEqual(row.c3,{type:'binary',base64:'AP8='});assert.equal(row.c4,(await a.query(`SELECT added FROM ${from} WHERE id=2`)).rows[0]?.c0,JSON.stringify({source:c.source.sql,draft:draft.sql,sourceMode:c.source.tableStructure!.sqlMode,targetMode:c.target.tableStructure!.sqlMode}));await b.query(`UPDATE ${to} SET v='after' WHERE id=77`);assert.equal((await b.query(`SELECT count(*) FROM ${audit}`)).rows[0]?.c0,1);assert.equal((await a.query(`SELECT v FROM ${from}`)).rows[0]?.c0,'source');assert.equal((await b.details(to)).foreignKeys.length,1);
  if(mysql){const comments=await b.query(`SELECT TABLE_COMMENT FROM information_schema.TABLES WHERE TABLE_SCHEMA='${schema}' AND TABLE_NAME IN ('${prefix}_a','${prefix}_b') ORDER BY TABLE_NAME`);assert.equal(comments.rows[0]?.c0,comments.rows[1]?.c0);await b.query(`INSERT INTO ${to}(v) VALUES('next')`);assert.equal((await b.query(`SELECT max(id) FROM ${to}`)).rows[0]?.c0,501);}
  const next=await comparisons.compare(...endpoints);assert.equal(next.differences.filter(v=>v.change!=='equal').length,0,JSON.stringify(next.differences.filter(v=>v.change!=='equal')));
  if(!mysql){
   const srcSchema=prefix+'_s',dstSchema=prefix+'_d',outside=name('_outside'),src=q(srcSchema)+'.scoped',dst=q(dstSchema)+'.scoped';
   try{await b.query(`CREATE SCHEMA ${q(srcSchema)}`);await b.query(`CREATE SCHEMA ${q(dstSchema)}`);await b.query(`CREATE TABLE ${outside}(id INT PRIMARY KEY)`);await b.query(`INSERT INTO ${outside} VALUES(1)`);await b.query(`CREATE TABLE ${src}(id INT PRIMARY KEY,p INT,CONSTRAINT fk_external FOREIGN KEY(p) REFERENCES ${outside}(id))`);await b.query(`CREATE TABLE ${dst}(id INT PRIMARY KEY,p INT)`);await b.query(`INSERT INTO ${dst} VALUES(1,1)`);
    const external=await comparisons.compare({profileId:source.id,table:src},{profileId:target.id,table:dst}),prepared=await comparisons.prepare(external.token,external.differences.filter(v=>v.change!=='equal'&&v.selectable).map(v=>v.id));assert(prepared.sql.includes(`REFERENCES ${q('public')}.${q(prefix+'_outside')}`));const review=await definitions.preview(prepared.baseline,prepared.sql);assert.equal(review.kind,'preview');if(review.kind!=='preview')throw Error('Expected external-FK plan');const applied=await definitions.apply(target.id,review.preview.token);assert.equal(applied.status,'succeeded',applied.error);assert.equal((await b.details(dst)).foreignKeys.length,1);
   }finally{await b.query(`DROP SCHEMA IF EXISTS ${q(dstSchema)} CASCADE`);await b.query(`DROP SCHEMA IF EXISTS ${q(srcSchema)} CASCADE`);await b.query(`DROP TABLE IF EXISTS ${outside}`);}
  }
  await sqlite.query('CREATE TABLE local(id INTEGER PRIMARY KEY,v TEXT)');const cross=await comparisons.compare({profileId:local.id,table:'local'},endpoints[1]);assert.equal(cross.canPrepare,true);assert(cross.differences.length>0);assert(cross.differences.every(v=>v.requiresReview));const selected=cross.differences.find(v=>v.change!=='equal'&&v.selectable);assert(selected);const proposed=await comparisons.prepare(cross.token,[selected.id]);assert.equal(proposed.baseline.profileId,target.id);
  await a.query(`ALTER TABLE ${from} ADD COLUMN external_change INT`);await assert.rejects(comparisons.prepare(next.token,next.differences.filter(v=>v.change!=='equal').map(v=>v.id).concat('missing')),/unavailable|unique/);
 }finally{
  try{const b=await manager.connect(target.id);await b.query(`DROP TABLE IF EXISTS ${to}`);await b.query(`DROP TABLE IF EXISTS ${from}`);await b.query(`DROP TABLE IF EXISTS ${audit}`);if(!mysql)await b.query(`DROP FUNCTION IF EXISTS ${name('_fn')}()`);}finally{await manager.close();}
 }
}
